type Etapa = "prospecto" | "contato" | "proposta" | "negociacao" | "fechado" | "perdido";

interface Lead {
  id: string;
  nome: string;
  empresa: string;
  cnpj: string;
  telefone: string;
  email: string;
  etapa: Etapa;
  valor_estimado: number | null;
  tipo_negocio: "orcamento" | "manutencao" | null;
  observacoes: string;
  prazo: string | null;
  proximo_contato: string | null;
  endereco_fiscal: string;
  endereco_atendimento: string;
  criado_em: string;
  cliente_id: string | null;
  data_inicio: string | null;
  data_fechamento: string | null;
}

interface ClienteVinculado {
  id: string;
  nome: string;
  cnpj: string | null;
  telefone: string | null;
  email: string | null;
}

interface Conversa {
  id: string;
  lead_id: string;
  texto: string;
  autor: string;
  criado_em: string;
}

interface Suprimento {
  id: string;
  nome: string;
  codigo: string;
  unidade: string;
  custo_unitario: number;
  tempo_instalacao_min: number;
  profissionais_ids: string[];
}

interface Profissional {
  id: string;
  nome: string;
  especialidade: string;
  tipo_cobranca: "diaria" | "por_unidade";  // diária = × dias do profissional; por_unidade = × qtd
  custo_diario: number;      // usado quando tipo_cobranca = "diaria"
  custo_unitario: number;    // usado quando tipo_cobranca = "por_unidade"
  ativo: boolean;
  terceirizado: boolean;     // false = Rafael Nunes (sem custo, tempo conta); true = terceirizado (tem custo)
}

interface ItemOrcamento {
  suprimento_id: string;
  nome: string;
  unidade: string;
  custo_unitario: number;   // preço de compra (editável pelo vendedor)
  quantidade: number;
  descricao: string;        // descrição/variação do item (ex: "90 min, 0,80x2,10m")
}

interface Orcamento {
  id?: string;
  lead_id: string;
  itens: ItemOrcamento[];
  custo_total: number;
  margem_pct: number;
  imposto_pct: number;
  preco_final: number;
  observacoes: string;
  criado_em?: string;
}

type StatusProposta = "criado" | "enviado" | "fechado" | "descontinuado";

interface ConteudoProposta {
  portas: number;
  parcela: number;
  custoCorretivo: number;
  frequencia: number;
  numProposta: string;
}

interface PropostaSalva {
  id: string;
  lead_id: string;
  tipo: "orcamento" | "manutencao";
  nome_arquivo: string;
  storage_path: string;
  status: StatusProposta;
  conteudo: ConteudoProposta | null;
  criado_em: string;
  atualizado_em: string | null;
  cliente_id: string | null;
  enviado_logistica: boolean;
  enviado_logistica_em: string | null;
  atendimento_id: string | null;
}

// Carrega pdfmake do CDN (singleton)
async function carregarPdfMake() {
  if ((window as Record<string, unknown>).pdfMake) return;
  await new Promise<void>((resolve, reject) => {
    const s1 = document.createElement("script");
    s1.src = "https://cdnjs.cloudflare.com/ajax/libs/pdfmake/0.2.7/pdfmake.min.js";
    s1.onload = () => {
      const s2 = document.createElement("script");
      s2.src = "https://cdnjs.cloudflare.com/ajax/libs/pdfmake/0.2.7/vfs_fonts.min.js";
      s2.onload = () => resolve();
      s2.onerror = reject;
      document.head.appendChild(s2);
    };
    s1.onerror = reject;
    document.head.appendChild(s1);
  });
}

// Salva metadados da proposta no Supabase (sem upload de PDF)
async function salvarPropostaDb(
  leadId: string,
  tipo: "orcamento" | "manutencao",
  nomeArquivo: string,
  conteudo: ConteudoProposta,
): Promise<PropostaSalva> {
  const storagePath = `${leadId}/${tipo}/${Date.now()}_${nomeArquivo}`;

  const { data, error } = await supabase.from("crm_propostas").insert({
    lead_id: leadId,
    tipo,
    nome_arquivo: nomeArquivo,
    storage_path: storagePath,
    status: "criado",
    conteudo,
  }).select().single();

  if (error) {
    console.error("Supabase crm_propostas INSERT error:", JSON.stringify(error));
    throw new Error(`Erro ao salvar proposta: ${error.message} (code: ${error.code})`);
  }

  // Auto-registrar entrada no Histórico
  const tipoLabel = tipo === "manutencao" ? "Manutenção 12×" : "Orçamento";
  await supabase.from("crm_conversas").insert({
    lead_id: leadId,
    texto: `📄 Proposta gerada: ${nomeArquivo} (${tipoLabel})`,
    autor: "Sistema",
  });

  return data as PropostaSalva;
}

// Salva o PDF no Supabase Storage e registra metadados na tabela (orçamento)
async function salvarPropostaStorage(
  leadId: string,
  tipo: "orcamento" | "manutencao",
  nomeArquivo: string,
  docDef: unknown,
): Promise<void> {
  const pm = (window as Record<string, unknown>).pdfMake as {
    createPdf: (def: unknown) => {
      download: (name: string) => void;
      getBlob: (cb: (blob: Blob) => void) => void;
    };
  };

  const blob = await new Promise<Blob>((resolve) => pm.createPdf(docDef).getBlob(resolve));

  const storagePath = `${leadId}/${tipo}/${Date.now()}_${nomeArquivo}`;
  const { error: upErr } = await supabase.storage
    .from("propostas")
    .upload(storagePath, blob, { contentType: "application/pdf", upsert: false });

  if (upErr) throw new Error(`Upload falhou: ${upErr.message}`);

  await supabase.from("crm_propostas").insert({
    lead_id: leadId,
    tipo,
    nome_arquivo: nomeArquivo,
    storage_path: storagePath,
    status: "criado",
    conteudo: null,
  });
}

